function PostEbook({go}){
 const Cta=window.MJCta;const {Kicker}=window.MnjauprrrrrDesignSystem_64b9d1;const P={...MJ_P,fontSize:20,color:'#000',margin:'0 0 16px',textWrap:'pretty',textAlign:'justify',hyphens:'auto'};
 const uloge=[['Kuća','GDE se radnja odvija?','scena, bina'],['Planeta','KO je glavni lik u predstavi?','glumac'],['Horoskopski znak','ŠTA tačno radi, sa koliko energije i na koji način?','uloge koje glumci igraju'],['Vladar kuće','ZBOG ČEGA ILI KOGA nešto radi?','energija scene'],['Aspekt','KAKO I ZAŠTO?','radnja predstave']];
 return <section style={{position:'relative',overflow:'hidden',background:'var(--sedef-2)',padding:'110px 0 120px'}}><div className="mj-leopard" style={{position:'absolute',inset:0,backgroundSize:'260px auto',opacity:.3,pointerEvents:'none'}}/><div style={{position:'absolute',inset:0,pointerEvents:'none',background:'radial-gradient(ellipse 50% 70% at 50% 45%, rgba(239,229,214,.88) 0%, rgba(239,229,214,.5) 65%, rgba(239,229,214,0) 100%)'}}/>
  <div style={{position:'relative',maxWidth:780,margin:'0 auto'}}>
   <a onClick={()=>go('blog')} style={{display:'inline-block',marginBottom:18,font:'600 12px Inter',letterSpacing:'.14em',textTransform:'uppercase',cursor:'pointer'}}>← Blog</a>
   <Kicker tone="ink">Psihoskop · odlomak iz e-knjige</Kicker>
   <h1 style={{...MJ_H1,color:'#000',margin:'12px 0 22px'}}>Zvezdana pozornica</h1>
   <p style={P}>Astronom, planetarni naučnik i komunikator, Karl Sagan poetski je rekao:</p>
   <p style={{margin:'6px 0 26px',fontFamily:'var(--font-script)',fontWeight:700,fontSize:34,lineHeight:1.2}}>„We are made of star stuff.”</p>
   <p style={P}>Dopada mi se da mislim da je život stvoren od istih elemenata od kojih su satkane zvezde i nebeska tela. Oduvek je ljude zanimalo šta će biti sutra.</p>
   <p style={P}>Svaki veliki vojskovođa i vladar imao je svog ličnog astrologa ili numerologa, tako da hajde da zajedno zavirimo u svet zvezda i otkrijemo njihov jezik.</p>
   <h2 style={{...MJ_H2,fontSize:24,color:'#000',margin:'34px 0 18px'}}>Natalna karta kao predstava</h2>
   <div style={{display:'grid',gap:10,marginBottom:30}}>{uloge.map(([a,b,c])=><div key={a} style={{display:'grid',gridTemplateColumns:'200px minmax(0,1fr)',gap:18,alignItems:'baseline',padding:'14px 20px',background:'rgba(255,255,255,.22)',backdropFilter:'blur(14px) saturate(1.25)',WebkitBackdropFilter:'blur(14px) saturate(1.25)',border:'1px solid rgba(255,255,255,.6)'}}><span style={{fontWeight:700,fontSize:20,lineHeight:1.3,color:'#000'}}>{a}</span><span style={{fontSize:20,lineHeight:1.5,color:'#000'}}><b>{b}</b> <i>({c})</i></span></div>)}</div>
   <h2 style={{...MJ_H2,fontSize:24,color:'#000',margin:'34px 0 14px'}}>Šta je natalni horoskop?</h2>
   <p style={P}>Položaj zvezda na nebu u trenutku tvog rođenja. Tvoj karakter, veštine, sposobnosti, način na koji deluješ i ono što daješ i primaš od svog okruženja jeste tvoj lični horoskop o kome nam zvezde pričaju.</p>
   <p style={P}>Ne postoji univerzalni lek niti predikcija koju jedna slobodna volja nije preveslala. Zvezde ti govore o tvojim potencijalima, mogućnostima i manje razvijenim osobinama. Kako ćeš ti to iskoristiti, predstavlja tvoj lični izbor.</p>
   <h2 style={{...MJ_H2,fontSize:24,color:'#000',margin:'34px 0 14px'}}>Ovan</h2>
   <div style={{position:'relative'}}><p style={P}>Ovan je čista sirova sila života koja se ne objašnjava, ona se doživljava. Kada dođe, ništa nije spremno, ali sve mora da se pokrene. To je znak buđenja, prvi uzdah posle mraka, trenutak kad krv udari u glavu i telo krene da se bori za svoje postojanje. On ne pita da li ima mesta, on se probija…</p><div style={{position:'absolute',left:0,right:0,bottom:0,height:70,background:'linear-gradient(180deg,rgba(239,229,214,0),rgba(239,229,214,.95))'}}/></div>
   <div style={{marginTop:40,padding:'40px 44px',background:'rgba(255,255,255,.3)',backdropFilter:'blur(16px) saturate(1.25)',WebkitBackdropFilter:'blur(16px) saturate(1.25)',border:'1px solid rgba(197,160,89,.7)',color:'#111',boxShadow:'0 16px 36px rgba(0,0,0,.12)',display:'grid',gridTemplateColumns:'minmax(0,1fr) minmax(220px,auto)',gap:30,alignItems:'center'}}>
    <div><div style={{fontSize:13,letterSpacing:'.2em',textTransform:'uppercase',fontWeight:500,marginBottom:8}}>Nastavak u e-knjizi</div><div style={{fontFamily:'var(--font-script)',fontWeight:700,fontSize:34,lineHeight:1,color:'#111'}}><span style={{display:'inline-block',paddingRight:6,backgroundImage:'linear-gradient(100deg,#111 0%,#111 40%,#C5A059 47%,#F3E2B8 50%,#C5A059 53%,#111 60%,#111 100%)',backgroundSize:'300% 100%',WebkitBackgroundClip:'text',backgroundClip:'text',WebkitTextFillColor:'transparent',animation:'mjShine 7s ease-in-out infinite'}}><style>{'@keyframes mjShine{0%{background-position:100% 0}60%,100%{background-position:0% 0}}'}</style>Zvezdana pozornica</span></div><p style={{margin:'12px 0 0',fontSize:20,lineHeight:1.6}}>Svih 12 znakova, kuće, planete i aspekti, da sama pročitaš svoju natalnu kartu. 68 strana · 25 €.<br/>Uz Aspekte paket je 30 €.</p></div>
    <div style={{display:'grid',gap:12,justifyItems:'start'}}><a href="mailto:marina.rakic1806@gmail.com?subject=E-knjiga%20Zvezdana%20pozornica" style={{fontFamily:'var(--font-script)',fontWeight:700,fontSize:34,lineHeight:1.1,whiteSpace:'nowrap',color:'#111',textDecoration:'underline',textDecorationThickness:1,textUnderlineOffset:6}}>Želim e-knjigu</a><a onClick={()=>go('astro')} style={{cursor:'pointer',fontSize:12,letterSpacing:'.14em',textTransform:'uppercase',color:'#111',textDecoration:'underline',textUnderlineOffset:4}}>Astro kutak</a></div>
   </div>
  </div></section>;
}
